UPDATE catalog_product_entity_text t JOIN catalog_product_entity e ON e.entity_id = t.entity_id SET t.value = '<!-- LSN_DATA: [{"title":"Topic 1: Generative AI for Visual Communication","subsecs":[{"title":"Introduction to Generative AI (GenAI)","links":[]},{"title":"Popular GenAI tools for image creation","links":[]},{"title":"Using text prompts to create images","links":[]},{"title":"Text prompt best practices","links":[]},{"title":"Elements of visual communication design","links":[]},{"title":"Best practices of visual communication","links":[]}]},{"title":"Topic 2: Generative AI with Adobe Firefly","subsecs":[{"title":"Generating images with content types and styles","links":[]},{"title":"Mixing images with Match Image","links":[]},{"title":"Setting colours, lighting and composition","links":[]},{"title":"Developing visual concepts and creative variations","links":[]},{"title":"Creating storyboards for visual narratives and task flows","links":[]},{"title":"Creating text effects","links":[]},{"title":"Creating design templates with Text to Template","links":[]}]},{"title":"Topic 3: Generative AI with Adobe Photoshop","subsecs":[{"title":"Using Generative Fill in Photoshop","links":[]},{"title":"Inserting objects and subjects","links":[]},{"title":"Removing subjects from an image","links":[]},{"title":"Selecting objects and people","links":[]},{"title":"Replacing image backgrounds and skies","links":[]},{"title":"Using multiple prompts","links":[]},{"title":"Generative Expand","links":[]},{"title":"Inpainting and outpainting","links":[]}]},{"title":"Topic 4: Enhancing and Refining AI-Generated Images","subsecs":[{"title":"Image composition and object manipulation","links":[]},{"title":"Colour fundamentals and colour correction","links":[]},{"title":"Modifying environments and fixing AI faces","links":[]},{"title":"Evaluating visual quality and applying design critique","links":[]},{"title":"Proposing enhancements to visual design","links":[]}]}] -->\n<p><strong>Topic 1: Generative AI for Visual Communication</strong></p>\n<p><em>Introduction to Generative AI (GenAI)</em></p>\n<p><em>Popular GenAI tools for image creation</em></p>\n<p><em>Using text prompts to create images</em></p>\n<p><em>Text prompt best practices</em></p>\n<p><em>Elements of visual communication design</em></p>\n<p><em>Best practices of visual communication</em></p>\n<p><strong>Topic 2: Generative AI with Adobe Firefly</strong></p>\n<p><em>Generating images with content types and styles</em></p>\n<p><em>Mixing images with Match Image</em></p>\n<p><em>Setting colours, lighting and composition</em></p>\n<p><em>Developing visual concepts and creative variations</em></p>\n<p><em>Creating storyboards for visual narratives and task flows</em></p>\n<p><em>Creating text effects</em></p>\n<p><em>Creating design templates with Text to Template</em></p>\n<p><strong>Topic 3: Generative AI with Adobe Photoshop</strong></p>\n<p><em>Using Generative Fill in Photoshop</em></p>\n<p><em>Inserting objects and subjects</em></p>\n<p><em>Removing subjects from an image</em></p>\n<p><em>Selecting objects and people</em></p>\n<p><em>Replacing image backgrounds and skies</em></p>\n<p><em>Using multiple prompts</em></p>\n<p><em>Generative Expand</em></p>\n<p><em>Inpainting and outpainting</em></p>\n<p><strong>Topic 4: Enhancing and Refining AI-Generated Images</strong></p>\n<p><em>Image composition and object manipulation</em></p>\n<p><em>Colour fundamentals and colour correction</em></p>\n<p><em>Modifying environments and fixing AI faces</em></p>\n<p><em>Evaluating visual quality and applying design critique</em></p>\n<p><em>Proposing enhancements to visual design</em></p>\n' WHERE @sg = 1 AND t.attribute_id = @a_desc AND t.store_id = 0 AND TRIM(e.sku) = 'C16' AND CHAR_LENGTH(t.value) = 3210;

